let csrfToken='';
const loginForm=document.querySelector('#login');
const key=document.querySelector('#key');
const status=document.querySelector('#status');
const error=document.querySelector('#error');
const panel=document.querySelector('#panel');
const output=document.querySelector('#credential');
const showError=(message='')=>{error.textContent=message;};
const request=async(path,options={})=>{const headers=new Headers(options.headers||{});const method=(options.method||'GET').toUpperCase();if(!['GET','HEAD','OPTIONS'].includes(method))headers.set('x-csrf-token',csrfToken);const response=await fetch(path,{...options,method,headers,credentials:'same-origin'});if(!response.ok)throw new Error((await response.text())||response.statusText);return response;};
const loadCredential=async()=>{const response=await request('/admin/credential');output.textContent=JSON.stringify(await response.json(),null,2);};
const loadSession=async()=>{try{const response=await request('/admin/auth/session');const value=await response.json();csrfToken=value.csrf_token||'';status.textContent='Signed in';panel.hidden=false;loginForm.hidden=true;showError();await loadCredential();return true;}catch{csrfToken='';status.textContent='Signed out';panel.hidden=true;loginForm.hidden=false;return false;}};
loginForm.addEventListener('submit',async event=>{event.preventDefault();showError();try{await request('/admin/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({api_key:key.value})});key.value='';await loadSession();}catch(cause){showError(cause.message);}});
document.querySelector('#refresh').addEventListener('click',async()=>{try{await request('/admin/credential/refresh',{method:'POST'});await loadCredential();}catch(cause){showError(cause.message);}});
document.querySelector('#logout').addEventListener('click',async()=>{try{await request('/admin/auth/logout',{method:'POST'});await loadSession();}catch(cause){showError(cause.message);}});
loadSession();